def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = []
    op = []
    opp_c = 0
    for a, b in history:
        my.append(a)
        op.append(b)
        if b == 'C':
            opp_c += 1

    opp_d = n - opp_c

    w = 10 if n >= 10 else n
    recent_opp_c = 0
    for i in range(n - w, n):
        if op[i] == 'C':
            recent_opp_c += 1

    punish = 0
    unprovoked = 0
    forgiving = 0
    for i in range(1, n):
        if op[i] == 'D':
            if my[i - 1] == 'D':
                punish += 1
            else:
                unprovoked += 1
        else:
            if my[i - 1] == 'D':
                forgiving += 1

    opp_d_streak = 0
    for x in reversed(op):
        if x == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for x in reversed(my):
        if x == 'D':
            my_d_streak += 1
        else:
            break

    opp_rate = opp_c / n

    chronic = False
    if opp_c == 0:
        chronic = True
    elif n >= 10 and recent_opp_c == 0 and opp_rate < 0.3:
        chronic = True
    elif n >= 20 and recent_opp_c <= 1 and opp_rate < 0.25:
        chronic = True
    elif opp_d_streak >= 12 and opp_rate < 0.2:
        chronic = True

    if chronic:
        return 'D'

    last_b = op[-1]
    prev_a = my[-2] if n >= 2 else 'C'

    if last_b == 'C':
        if n >= 98:
            if opp_d == 0:
                return 'D'
            if punish == 0 and forgiving > 0 and opp_rate > 0.65:
                return 'D'
            if punish == 0 and unprovoked == 0 and opp_rate > 0.85:
                return 'D'
            return 'C'

        if forgiving >= 1 and punish == 0 and opp_rate > 0.7 and 1 <= my_d_streak < 3:
            return 'D'

        return 'C'

    if n == 1:
        return 'D'

    if prev_a == 'D':
        if opp_rate < 0.2 or recent_opp_c == 0:
            return 'D'
        if opp_d_streak >= 6 and opp_rate < 0.35:
            return 'D'
        return 'C'

    if opp_rate > 0.85 and unprovoked <= 1 and punish == 0 and rng.random() < 0.2:
        return 'C'

    return 'D'
